From 3c9e412280cb589640cc7a1ae80ca06d8a32f296 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:28:26 +0100
Subject: [PATCH] components/batterycontrol: number batteries that share a
 device name

Devices like earbuds or split keyboards now show up with one battery per
part, but all of them got the same name, making them indistinguishable in
the Power and Battery widget. Each one now gets a "Battery N" suffix.

BUG: 518513
---
 components/batterycontrol/batterycontrol.cpp | 36 +++++++++++++++++++-
 components/batterycontrol/batterycontrol.h   |  2 ++
 2 files changed, 37 insertions(+), 1 deletion(-)

diff --git a/components/batterycontrol/batterycontrol.cpp b/components/batterycontrol/batterycontrol.cpp
index 060d5895ac..85da7edb76 100644
--- a/components/batterycontrol/batterycontrol.cpp
+++ b/components/batterycontrol/batterycontrol.cpp
@@ -8,6 +8,7 @@

 #include "batterycontrol_debug.h"

+#include <QCollator>
 #include <QDBusConnectionInterface>
 #include <QDBusInterface>
 #include <QDBusMetaType>
@@ -272,13 +273,43 @@ QVariant BatteryControlModel::data(const QModelIndex &index, int role) const
     case ChargeState:
         return QVariant::fromValue(updateBatteryState(battery));
     case PrettyName:
-        return QVariant::fromValue(m_namesMonitor->updateBatteryName(*battery));
+        return QVariant::fromValue(batteryName(battery));
     case Type:
         return QVariant::fromValue(batteryTypeToString(battery));
     }
     return {};
 }

+QString BatteryControlModel::batteryName(const UPowerBattery *battery) const
+{
+    const QString name = m_namesMonitor->updateBatteryName(*battery);
+
+    QStringList sameNameUdis;
+    for (const auto &[udi, otherBattery] : m_batteries) {
+        if (m_namesMonitor->updateBatteryName(*otherBattery) == name) {
+            sameNameUdis.append(udi);
+        }
+    }
+    if (sameNameUdis.size() < 2) {
+        return name;
+    }
+
+    QCollator collator;
+    collator.setNumericMode(true);
+    std::ranges::sort(sameNameUdis, collator);
+    return i18nc("@label %1 is the name of a device with several batteries, %2 is the number of one of them",
+                 "%1 (Battery %2)",
+                 name,
+                 sameNameUdis.indexOf(battery->udi()) + 1);
+}
+
+void BatteryControlModel::updateBatteryNames()
+{
+    if (!m_batterySources.isEmpty()) {
+        Q_EMIT dataChanged(index(0), index(m_batterySources.size() - 1), {PrettyName});
+    }
+}
+
 QHash<int, QByteArray> BatteryControlModel::roleNames() const
 {
     QHash<int, QByteArray> roles;
@@ -379,6 +410,7 @@ void BatteryControlModel::addBattery(std::unique_ptr<UPowerBattery> newBattery)

     m_hasBatteries = true;

+    updateBatteryNames();
     updateOverallBattery();
 }

@@ -426,6 +458,8 @@ void BatteryControlModel::deviceRemoved(const QString &udi)
     m_batteries.erase(udi);
     m_batteryOrder.remove(udi);

+    updateBatteryNames();
+
     if (wasInternal) {
         updateOverallBattery();
     }
diff --git a/components/batterycontrol/batterycontrol.h b/components/batterycontrol/batterycontrol.h
index c847bd424f..b6540380b3 100644
--- a/components/batterycontrol/batterycontrol.h
+++ b/components/batterycontrol/batterycontrol.h
@@ -77,6 +77,8 @@ private:

     ChargeStateEnum updateBatteryState(const UPowerBattery *battery) const;
     QString batteryTypeToString(const UPowerBattery *battery) const;
+    QString batteryName(const UPowerBattery *battery) const;
+    void updateBatteryNames();

     void addBattery(std::unique_ptr<UPowerBattery> newBattery);
     void onBatteryChanged(const QString &udi, const QList<int> &roles, bool overallChanged);
